+      filter: brightness(1.08);
+      transform: translateY(-1px);
+    }
+
+    button:focus-visible,
+    input[type="checkbox"]:focus-visible {
+      outline: 3px solid var(--success);
+      outline-offset: 3px;
+    }
+
+    #results {
+      margin-top: 22px;
+      padding: 18px;
+      border: 1px solid rgba(52, 211, 153, 0.45);
+      border-radius: 16px;
+      color: #d1fae5;
+      background: rgba(6, 78, 59, 0.28);
+    }
+
+    #results:empty {
+      display: none;
+    }
+
+    @media (max-width: 560px) {
+      main {
+        padding: 24px 0;
+      }
+
+      .quiz-card {
+        padding: 22px;
+      }
+
+      .form-field {
+        padding: 18px;
+      }
+    }
+  </style>
+</head>
+<body>
+  <main>
+    <section class="quiz-card" aria-labelledby="quiz-title">
+      <h1 id="quiz-title">Computer Languages Quiz</h1>
+      <p class="intro">Choose every answer that applies. Some questions have more than one correct response.</p>
+
+      <form id="quiz-form">
+        <div class="form-field">
+          <fieldset>
+            <legend>1. Which of these are commonly used as programming languages?</legend>
+            <p class="help-text" id="q1-help">Select all languages used to write software, scripts, or applications.</p>
+            <div class="choices" aria-describedby="q1-help">
+              <label><input type="checkbox" name="q1" value="Python"> Python</label>
+              <label><input type="checkbox" name="q1" value="JavaScript"> JavaScript</label>
+              <label><input type="checkbox" name="q1" value="HTML"> HTML</label>
+              <label><input type="checkbox" name="q1" value="Ruby"> Ruby</label>
+            </div>
+          </fieldset>
+        </div>
+
+        <div class="form-field">
+          <fieldset>
+            <legend>2. Which languages are often used for web development?</legend>
+            <div class="choices">
+              <label><input type="checkbox" name="q2" value="JavaScript"> JavaScript</label>
+              <label><input type="checkbox" name="q2" value="TypeScript"> TypeScript</label>
+              <label><input type="checkbox" name="q2" value="CSS"> CSS</label>
+              <label><input type="checkbox" name="q2" value="SQL"> SQL</label>
+            </div>
+          </fieldset>
+        </div>
+
+        <div class="form-field">
+          <fieldset>
+            <legend>3. Which languages are known for systems programming?</legend>
+            <div class="choices">
+              <label><input type="checkbox" name="q3" value="C"> C</label>
+              <label><input type="checkbox" name="q3" value="Rust"> Rust</label>
+              <label><input type="checkbox" name="q3" value="Go"> Go</label>
+              <label><input type="checkbox" name="q3" value="Markdown"> Markdown</label>
+            </div>
+          </fieldset>
+        </div>
+
+        <button type="submit">Submit quiz</button>
+      </form>
+
+      <div id="results" role="status" aria-live="polite"></div>
+    </section>
+  </main>
+
+  <script>
+    const form = document.querySelector("#quiz-form");
+    const results = document.querySelector("#results");
+
+    form.addEventListener("submit", (event) => {
+      event.preventDefault();
+
+      const answerSummary = ["q1", "q2", "q3"].map((questionName, index) => {
+        const selected = [...form.querySelectorAll(`input[name="${questionName}"]:checked`)]
+          .map((input) => input.value);
+        const answerText = selected.length > 0 ? selected.join(", ") : "No answers selected";
+
+        return `Question ${index + 1}: ${answerText}`;
+      });
+
+      results.innerHTML = `<strong>Your selections:</strong><br>${answerSummary.join("<br>")}`;
+    });
+  </script>
+</body>
+</html>
*** End Patch
