      margin: 0 0 24px;
      padding: 22px;
      border: 1px solid var(--border);
      border-radius: 18px;
      background: linear-gradient(180deg, rgba(31, 41, 55, 0.86), rgba(17, 24, 39, 0.86));
    }

    fieldset {
      min-width: 0;
      margin: 0;
      padding: 0;
      border: 0;
    }

    legend {
      margin-bottom: 6px;
      font-size: 1.08rem;
      font-weight: 700;
    }

    .help-text {
      margin: 0 0 16px;
      color: var(--muted);
      font-size: 0.95rem;
    }

    .choices {
      display: grid;
      gap: 12px;
      margin-top: 14px;
    }

    label {
      display: flex;
      align-items: flex-start;
      gap: 12px;
      padding: 13px 14px;
      border: 1px solid rgba(148, 163, 184, 0.22);
      border-radius: 14px;
      color: var(--text);
      background: rgba(15, 23, 42, 0.7);
      cursor: pointer;
      transition: border-color 160ms ease, background-color 160ms ease, transform 160ms ease;
    }

    label:hover {
      border-color: rgba(96, 165, 250, 0.7);
      background: rgba(30, 41, 59, 0.95);
      transform: translateY(-1px);
    }

    input[type="checkbox"] {
      width: 1.15rem;
      height: 1.15rem;
      margin-top: 0.16rem;
      accent-color: var(--accent);
      flex: 0 0 auto;
    }

    button {
      width: 100%;
      padding: 15px 18px;
      border: 0;
      border-radius: 16px;
      color: #ffffff;
      background: linear-gradient(135deg, var(--accent-strong), #2563eb);
      box-shadow: 0 14px 30px rgba(37, 99, 235, 0.32);
      font-size: 1rem;
